-- DOA 符合性检查单的 66 条条目（来自 UG-DAM-01-附3 00 草案）。
--
-- 依据 UG-RPT-2026-003 G 版第十一章。本迁移只种**条目本身**——要求编号、名称、
-- 原文、来源、适用性。这三样是体系文件里相对稳定的事实, 适合作为主数据。
--
-- 【刻意不种的两样，理由要说清楚】
--
-- 1. 条款级引用(das_checklist_doc_ref)不自动解析。
--    附3 该栏在 00 草案里至少有三种写法:
--      "UG-DAM-01 0.2；UG-DAP-01；版次 00（修订草案）"        编号+条款, 版本统一在末尾
--      "UG-DAM-01 设计保证手册 00（修订草案）第 2 章；..."     编号+名称+版本+章内联
--      "UG-DAP-02、UG-DAP-13～15"                              范围写法
--    严格模式只能匹配 33/66。解析错的引用和解析对的长得一模一样, 挂上去就成了
--    看起来有依据实际没有——比留空更糟。故原文逐字存入 source_doc_ref_raw,
--    由适航管理负责人对照转录(判据 EV1 要求 编号+名称+版本+条款号 四样齐全)。
--
-- 2. 符合性自评(das_checklist_assessment)不种。
--    填写说明 A26: 首次发布和申请前须由适航管理负责人结合实际范围、证件和运行证据
--    **逐项签署确认**。自评带签署人, 签署是人做的事, 种不出来。
--    附3 草案里那一栏的现有文字同样存入 source_doc_ref_raw 的姊妹位置(备注),
--    供转录时参考, 但不构成已签署的自评。
--
-- 适用性取三值: 是 38 条、否 12 条、部分 16 条。"部分"计入覆盖率分母——
-- 部分适用仍须覆盖, 只有 STC 与 PMA 都是"否"才排除(判据 EV5)。
--
-- 可重复执行: 按 seq 冲突则不插入, 不覆盖已有的人工修改。

INSERT INTO das_checklist_item
       (seq, req_code, req_name, req_text, req_source,
        applicable_stc, applicable_pma, na_reason, note, source_doc_ref_raw)
VALUES
(1, 'CCAR-21.1', '目的和依据', '为保障民用航空产品和零部件的适航性，根据《中华人民共和国民用航空法》《中华人民共和国行政许可法》和《中华人民共和国民用航空器适航管理条例》制定本规定。', 'CCAR-21', '是', '是', NULL, '完整原文：法规原文!A2:D2；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 0.2；UG-DAP-01；版次 00（修订草案），名称见文件索引'),
(2, 'CCAR-21.2A', '适用范围', '本规定适用于民用航空产品和零部件的型号合格审定、生产许可审定和适航合格审定，包括下列证件的申请、颁发和管理：（一）型号合格证；（二）补充型号合格证；（三）改装设计批准书；（四）型号认可证；（五）补充型号认可证；（六）零部件设计批准认可证；（七）生产许可证；（八）零部件制造人批准书；（九）技术标准规定项目批准书；（十）适航证；（十一）出口适航证；（十二）外国适航证认可书；（十三）特许飞行证；（十四）适航批准标签。', 'CCAR-21', '是', '是', NULL, '完整原文：法规原文!A3:D3；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 2；UG-DAP-09；版次 00（修订草案），名称见文件索引'),
(3, 'CCAR-21.2B', '定义', '本条完整要求分 3 段列于“法规原文”第 4～6 行，须连续逐款核对。
要求主题：CCAR-21.2B 定义
不得仅依据本行的自评说明代替条款全文。', 'CCAR-21', '是', '是', NULL, '完整原文：法规原文!A4:D6；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 缩略语；UG-DAP-01；版次 00（修订草案），名称见文件索引'),
(4, 'CCAR-21.2C', '溯及力', '（一）1987年6月1日（含）以后设计、制造民用航空产品，应当遵守本规定。（二）1987年6月1日以前已经按照中华人民共和国的有关规定进行过设计定型的航空产品，如果用于民用航空活动应当符合下列规定：1.可以不再申请型号合格证，但是对涉及安全和适航性的缺陷，局方将按照有关适航规章，要求对其进行必要的改装或者规定必要的使用限制；2.1987年6月l日（含）以后对上述民用航空产品进行设计更改，应当遵守本规定第三章、第四章；3.民用航空产品的设计人或者制造人如继续生产，应当遵守本规定第五章、第六章和第七章；4.军用航空产品的设计人或者制造人如继续生产，应当遵守本规定第二章、第五章、第六章和第七章。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A7:D7；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-01、UG-DAP-12、UG-DAP-14；版次 00（修订草案），名称见文件索引'),
(5, 'CCAR-21.2D', '合格审定程序和职责', '本条完整要求分 2 段列于“法规原文”第 8～9 行，须连续逐款核对。
要求主题：CCAR-21.2D 合格审定程序和职责
不得仅依据本行的自评说明代替条款全文。', 'CCAR-21', '是', '是', NULL, '完整原文：法规原文!A8:D9；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09 6；UG-DAP-15；版次 00（修订草案），名称见文件索引'),
(6, 'CCAR-21.3', '豁免', '（一）受适航规章和环境保护要求中有关条款约束的人，可以因技术原因向民航局申请暂时或者永久豁免某些条款。（二）申请人应当向民航局提交包括下述内容的申请豁免报告：1.请求豁免的适航规章或者环境保护要求及其具体条款；2.豁免的原因以及为保证具有可接受的安全水平所采取的措施和限制；3.豁免涉及的范围，包括航空器及适用期限；4.申请人的名称、地址，如为法人还应当包括法定代表人的姓名、职务。（三）民航局应当在收到评审组提交的评审报告后做出是否批准豁免的决定，必要时在批准前征求公众意见。', 'CCAR-21', '是', '是', NULL, '完整原文：法规原文!A10:D10；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-15 6；UG-DAP-07 6；版次 00（修订草案），名称见文件索引'),
(7, 'CCAR-21.4', '飞行手册', '航空器型号合格证、补充型号合格证、改装设计批准书持有人或者其权益转让协议受让人，或者型号认可证、补充型号认可证持有人应当在每架航空器交付给使用人时，在航空器上提供现行有效的飞行手册。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A11:D11；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-11 6；版次 00（修订草案），名称见文件索引'),
(8, 'CCAR-21.5', '故障、失效和缺陷的报告', '本条完整要求分 3 段列于“法规原文”第 12～14 行，须连续逐款核对。
要求主题：CCAR-21.5 故障、失效和缺陷的报告
不得仅依据本行的自评说明代替条款全文。', 'CCAR-21', '是', '是', NULL, '完整原文：法规原文!A12:D14；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 5；UG-DAP-12 6；UG-DAF-08；版次 00（修订草案），名称见文件索引'),
(9, 'CCAR-21.8', '运输类飞机的持续适航和安全改进', '（一）设计批准持有人和申请人应当符合《运输类飞机的持续适航和安全改进规定》（CCAR26）中适用的持续适航和安全改进的要求。（二）新生产的运输类飞机，设计批准持有人或者设计批准权益转让协议受让人应当符合《运输类飞机的持续适航和安全改进规定》（CCAR26）中适用于新生产的飞机的持续适航和安全改进要求。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A15:D15；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09、UG-DAP-11；版次 00（修订草案），名称见文件索引'),
(10, 'CCAR-21.9', '零部件的批准', '零部件的批准方式包括：（一）根据本规定第九章的第21.301条至第21.320条颁发零部件制造人批准书；（二）根据本规定第十章的第21.351条至第21.370条颁发技术标准规定项目批准书；（三）根据本规定第十章的第21.371条颁发零部件设计批准认可证；（四）随民用航空产品的型号合格审定、补充型号合格审定或者改装设计批准合格审定一起批准；（五）随民用航空产品的型号认可合格审定或者补充型号认可合格审定一起批准；（六）民航局规定的其他方式。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A16:D16；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09 6；UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(11, 'CCAR-21.10', '替换件和改装件', '（一）安装在经型号合格审定或者经型号认可审定的民用航空产品上的替换件或者改装件应当符合下列条件之一：1.依据型号合格证生产的；2.依据局方的生产批准生产的；3.标准件（例如螺栓或者螺母）；4.航空器所有人或者占有人按照局方规定为维修或者改装自己的航空器而生产的零部件；5.根据《民用航空器维修单位合格审定规定》（CCAR145）的规定，在维修许可证持有人批准维修项目范围内，在其质量系统控制下制造的、在民用航空产品或者零部件修理或者改装中消耗的零部件。（二）除第（一）款第1项和第2项外，任何人不得声明其生产用于销售目的的替换件或者改装件适合安装在经型号合格审定或者经型号认可审定的民用航空产品上。', 'CCAR-21', '是', '是', NULL, '完整原文：法规原文!A17:D17；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-04、UG-DAP-09、UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(12, 'CCAR-21.111', '适用范围', '本章适用于补充型号合格证、改装设计批准书和补充型号认可证的颁发以及对上述证件持有人的管理。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A18:D18；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 2；UG-DAP-09；版次 00（修订草案），名称见文件索引'),
(13, 'CCAR-21.112', '补充型号合格证、改装设计批准书和补充型号认可证的要求', '（一）型号合格证持有人对型号设计进行尚未达到按本规定第21.19条要求应当申请新型号合格证的大改时，该证件持有人可以申请补充型号合格证，或者按照第三章的规定申请对原证件的更改。（二）除本条第（三）款规定外，非型号合格证持有人对民用航空产品的型号设计进行尚未达到按本规定第21.19条要求应当申请新型号合格证的大改时，该申请人应当申请补充型号合格证；进行小改时，该申请人可申请改装设计批准书。（三）如果民用航空产品已获得型号合格证或者型号认可证，国外适航当局颁发的补充型号合格证持有人可以申请补充型号认可证。（四）已经表明或者正在表明具有符合第十四章要求的设计保证系统的人具备申请补充型号合格证或者改装设计批准书的资格。（五）申请人应当按照规定的格式向局方申请补充型号合格证或者改装设计批准书。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A19:D19；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-06、UG-DAP-09；版次 00（修订草案），名称见文件索引'),
(14, 'CCAR-21.113', '适用要求', '（一）补充型号合格证、改装设计批准书或者补充型号认可证申请人应当表明更改后的民用航空产品符合第21.101条规定的适用要求；对于第21.93条第（二）款规定的噪声更改，应当表明符合《航空器型号和适航合格审定噪声规定》（CCAR36）中的相关噪声要求；对于第21.93条第（三）款规定的排放更改，应当表明符合《涡轮发动机飞机燃油排泄和排气排出物规定》（CCAR34）中的相关燃油排泄和排气排出物要求。（二）对于对型号设计的每一更改，补充型号合格证、改装设计批准书或者补充型号认可证申请人应当符合第21.33条和第21.53条的规定。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A20:D20；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09 6；版次 00（修订草案），名称见文件索引'),
(15, 'CCAR-21.114', '补充型号合格证和改装设计批准书的颁发', '（一）局方确定申请人符合第21.112条和第21.113条的要求并且具有符合第十四章要求的设计保证系统后，申请人可以取得补充型号合格证或者改装设计批准书。（二）补充型号合格证数据单是补充型号合格证的一部分，改装设计批准书数据单是改装设计批准书的一部分，应当包括以下内容：1.民用航空产品型号设计更改的批准；2.该民用航空产品原型号合格证或者型号认可证；3.型号设计更改的描述、使用限制、局方审查确认已符合的有关适航要求和环境保护要求，以及对民用航空产品所规定的其他条件或者限制。（三）除局方另行规定终止日期外，补充型号合格证、改装设计批准书长期有效。（四）局方确认必要时，补充型号合格证、改装设计批准书持有人应当提交相应证件供检查。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A21:D21；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-07、UG-DAP-09；版次 00（修订草案），名称见文件索引'),
(16, 'CCAR-21.115', '补充型号认可证的颁发', '（一）在受理补充型号认可证的申请之前，局方应当确认中国与该民用航空产品的设计国已经签署民用航空产品进口和出口的适航协议、备忘录或者技术性协议。（二）补充型号认可证申请人应当向局方提交下述资料：1.按照局方规定格式填写的补充型号认可证申请书；2.国外适航当局颁发的补充型号合格证；3.设计更改所依据的适航规章、修正案、专用条件及豁免条款的批准；4.证明符合本规定第21.113条的资料；5.符合局方确定的审定基础的声明书；6.局方确认必要的其他资料。（三）局方审查本条第（二）款规定的资料并且进行必要的实地检查后，确认该设计更改符合下述要求，颁发补充型号认可证：1.第21.113条所确定的有关适航要求，或者民用航空产品设计国的有关适航要求和局方为使安全水平等效于第21.113条的规定而提出的任何其他要求；2.第21.113条所确定的环境保护要求，或者民用航空产品设计国的环境保护要求和为使噪声和燃油排放物水平不超过第21.113条的规定局方提出的任何其他要求。（四）补充型号认可证数据单是补充型号认可证的一部分，内容应当包括：1.民用航空产品型号设计更改的批准；2.该民用航空产品原型号合格证和型号认可证；3.型号设计更改的描述、使用限制、局方审查确认已符合的有关适航要求和环境保护要求，以及对民用航空产品所规定的其他条件或者限制；和4.设计国适航当局颁发的补充型号合格证的适用内容。（五）有关适航规章、噪声规定所要求的手册、标牌、目录清单和仪表标记应当用中文或者英文书写，下列各项应当至少有中文表述：1.机上所有对旅客进行的提示、警告和通知的文字标记和标牌；2.机上所有向旅客或者机外营救人员指示应急出口和门的位置以及开启方法的文字标记和标牌；3.旅客可能使用的机上所有应急设备的操作、使用说明。（六）除局方另行规定终止日期外，补充型号认可证长期有效。局方确认必要时，补充型号认可证持有人应当提交相应证件供检查。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A22:D23；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(17, 'CCAR-21.116', '转让性和持续适航文件', '（一）补充型号合格证或者改装设计批准书持有人可以将其设计资料根据权益转让协议供他人使用。证件持有人应当在权益转让协议签署生效和终止后30天内书面通知局方。通知书应当写明权益转让协议受让人的姓名、地址、权限范围和生效日期。（二）补充型号合格证、改装设计批准书或者补充型号认可证持有人应当向用户提供一套符合第21.50条要求的完整的持续适航文件，并应当使得这些持续适航文件可被那些被要求符合它的其他人员或者单位获得。此外，这些持续适航文件的修订应当可被那些被要求符合它的任何人员或者单位获得。（三）补充型号认可证不得转让。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A24:D24；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-11 6 步骤 4、16；版次 00（修订草案），名称见文件索引'),
(18, 'CCAR-21.117', '持证人的责任', '补充型号合格证或者改装设计批准书持有人应当承担以下所有责任：（一）持续保持符合第十四章要求的设计保证系统；（二）承担第21.5条、第21.6条、第21.8条、第21.99条和第21.116条规定的责任；（三）按照第十二章"标牌或者标记"的要求设置标牌或者标记。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A25:D25；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-11、UG-DAP-12、UG-DAP-13；版次 00（修订草案），名称见文件索引'),
(19, 'CCAR-21.118', '持证人的权利', '补充型号合格证和改装设计批准书持有人享有以下权利：（一）对于航空器，符合本规定第七章相关规定时，可以获得适航证；（二）对于发动机或者螺旋桨，可以安装在经审定的航空器上；（三）符合本规定第六章相关规定时，可以获得该补充型号合格证或者改装设计批准书批准的型号设计更改的生产许可证。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A26:D26；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09、UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(20, 'CCAR-21.119', '补充型号合格证或者改装设计批准书持有人提供书面许可协议的责任', '补充型号合格证或者改装设计批准书持有人允许他人使用其持有的证件改装航空器、航空发动机或者螺旋桨时，应当向对方提供局方可接受的书面许可协议。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A27:D27；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-11 6 步骤 17；UG-DAP-10 6 步骤 10；版次 00（修订草案），名称见文件索引'),
(21, 'CCAR-21.211', '适用范围', '本章适用于民用航空器特许飞行证的申请、颁发和管理。', 'CCAR-21', '部分', '否', NULL, '完整原文：法规原文!A28:D28；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(22, 'CCAR-21.212', '特许飞行证分类', '特许飞行证分为第一类特许飞行证和第二类特许飞行证。（一）从事下列飞行之一的尚未取得有效适航证的民用航空器，应当取得第一类特许飞行证：1.为试验航空器新的设计构思、新设备、新安装、新操作技术及新用途而进行的飞行；2.为证明符合适航标准而进行的试验飞行，包括证明符合型号合格证、补充型号合格证和改装设计批准书的飞行、证实重要设计更改的飞行、证明符合标准的功能和可靠性要求的飞行；3.新航空器的生产试飞；4.制造人为交付或者出口航空器而进行的调机飞行；5.制造人为训练机组而进行的飞行；6.为航空比赛或者展示航空器的飞行能力、性能和不寻常特性而进行的飞行，包括飞往和飞离比赛、展览、拍摄场所的飞行；7.为航空器市场调查和销售而进行的表演飞行；8.交付试飞；9.局方同意的其他飞行。（二）从事下列飞行之一的尚未取得有效适航证或者目前可能不符合有关适航要求但在一定限制条件下能安全飞行的航空器，应当取得第二类特许飞行证：1.为改装、修理航空器而进行的调机飞行；2.营运人为交付或者出口航空器而进行的调机飞行；3.为撤离发生危险的地区而进行的飞行；4.局方确认必要的其他飞行。', 'CCAR-21', '部分', '否', NULL, '完整原文：法规原文!A29:D29；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(23, 'CCAR-21.213', '特许飞行证的申请和颁发', '（一）民用航空器的所有人或者占有人可以申请该航空器的特许飞行证；（二）申请人应当按照规定的格式提交申请书；（三）局方接到申请后进行审查，提出确保飞行安全的限制条件，颁发规定了明确类别和必要限制的特许飞行证。', 'CCAR-21', '部分', '否', NULL, '完整原文：法规原文!A30:D30；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(24, 'CCAR-21.214', '特许飞行的基本要求和限制', '（一）尚未进行国籍登记的航空器做特许飞行前，应当向局方申请临时登记标志并获得临时登记证书。（二）申请人应当按照规定在该航空器的外表上制作局方指定的临时登记标志。（三）取得特许飞行证的航空器不得用于以营利为目的的运输或者作业飞行。（四）做特许飞行的航空器应当由持有局方颁发或者认可的相应执照的飞行机组人员驾驶，并且不得载运与该次飞行作业无关的人员；该航空器的飞行机组成员和其他有关人员应当确知该次特许飞行的情况和有关要求与措施。（五）特许飞行应当遵守相应的飞行规则，并且应当避开空中交通繁忙的区域、人口稠密地区以及可能对公众安全造成危害的区域。（六）特许飞行应当在飞行手册所规定的性能限制以及局方对该次特许飞行所提出的其他限制条件下进行。（七）除非得到飞越国的同意，否则不得使用特许飞行证飞越该国领空。', 'CCAR-21', '部分', '否', NULL, '完整原文：法规原文!A31:D31；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(25, 'CCAR-21.215', '特许飞行证的有效期', '特许飞行证的有效期由局方规定。', 'CCAR-21', '部分', '否', NULL, '完整原文：法规原文!A32:D32；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(26, 'CCAR-21.301', '适用范围', '本章适用于零部件制造人批准书的颁发及对其持有人的管理。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A33:D33；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 2；UG-DAP-09；版次 00（修订草案），名称见文件索引'),
(27, 'CCAR-21.302', '零部件制造人批准书申请人的资格', '已经表明或者正在表明具有符合第十四章要求的设计保证系统的人具备申请零部件制造人批准书的资格。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A34:D34；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09；版次 00（修订草案），名称见文件索引'),
(28, 'CCAR-21.303', '零部件制造人批准书的申请', '申请零部件制造人批准书的规定如下：（一）申请人应当按照规定的格式和方式提交零部件制造人批准书的申请，并同时提交下列资料：1.拟装用该零部件的民用航空产品的名称和型号。2.生产该零部件的生产设施的名称和地址。3.零部件的设计，至少包括下列资料：（1）说明该零部件构型所必需的图纸和规范；（2）确定该零部件的结构强度所必需的尺寸、材料和工艺。4.表明该零部件的设计符合拟安装该零部件的民用航空产品适用的适航规章的必要的试验和计算报告，但申请人能证明该零部件的设计与型号合格证、补充型号合格证或者改装设计批准书中批准的零部件的设计相同的除外。如果该零部件的设计是根据设计转让协议获得的，还应当提供该协议。5.通过试验和计算报告表明符合性的零部件制造人批准书申请人应当提交一份声明，申明其已经符合适航规章的要求。6.对第十四章要求的设计保证系统的符合性说明。（二）零部件制造人批准书的申请人应当进行所有必要的检验和试验，以确定：1.该零部件的设计符合有关的适航要求；2.该零部件的材料符合设计中的技术规范；3.该零部件符合经批准的设计；4.该零部件的制造工艺、构造和装配符合设计中的相应规定。（三）申请书的有效期为二年。（四）申请人在提交申请书的同时，还应当提交第21.308条规定的质量手册。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A35:D36；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09 6；UG-DAP-07；版次 00（修订草案），名称见文件索引'),
(29, 'CCAR-21.305', '机构', '零部件制造人批准书申请人或者持有人应当向局方提交相关说明文件，以表明其组织机构如何确保符合本章的要求。说明文件中至少应当描述组织机构中各个部门的职责和权限，责任经理、质量经理和质量系统人员的职责和权限，以及质量部门与行政管理部门和其他部门的职能关系。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A37:D37；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09 6 步骤 3；UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(30, 'CCAR-21.310', '检查和试验', '（一）零部件制造人批准书申请人和持有人应当接受局方为了确定符合涉及民航管理的规章，实施对设计保证系统、质量系统、设施、技术资料和任何生产的零部件的检查，并且目击任何试验，包括在供应商设施进行的任何检验或者试验。（二）除非局方同意，申请人或者持证人应当遵守下列要求：1.在证明其符合第21.303条第（二）款2至4项的要求之前，不得将零部件提交局方进行检查或者试验；2.完成第21.303条第（二）款2至4项的工作之后，到提交局方进行检查或者试验之前，不得对该零部件作任何更改。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A38:D38；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-07 6 步骤 3～6；UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(31, 'CCAR-21.311', '零部件制造人批准书的颁发', '（一）局方确定申请人具有可接受的设计保证系统，符合本章的要求并且零部件设计符合拟装该零部件的民用航空产品适用的涉及民航管理的规章的要求，即可颁发零部件制造人批准书，批准其按第21.308条所规定的质量手册生产该零部件。（二）零部件制造人批准书项目单是零部件制造人批准书的一部分，内容包括：零部件名称，型号，件号，适用的航空器、发动机或者螺旋桨的被替换的零部件制造人及其零部件件号，型别，序列号，注册号，设计批准依据，以及是否为关键件。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A39:D39；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09 6；UG-DAP-15；版次 00（修订草案），名称见文件索引'),
(32, 'CCAR-21.313', '有效期和转让性', '（一）除局方另行规定终止日期外，零部件制造人批准书长期有效，其项目单有效期为二年。（二）零部件制造人批准书不得转让。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A40:D40；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-15 6 步骤 7；UG-DAW-001；版次 00（修订草案），名称见文件索引'),
(33, 'CCAR-21.314', '适航批准', '除局方要求检查依据零部件制造人批准书生产的零部件（以下简称PMA件）是否符合经批准的设计外，零部件制造人批准书持有人无需进一步证明即可获得PMA件的适航批准标签。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A41:D41；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-09、UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(34, 'CCAR-21.316', '零部件制造人批准书持有人的责任', '（一）持续保持设计保证系统。（二）需要表明机构变化时，修订第21.305条要求的说明文件，并提交给局方。（三）保持质量系统符合获得零部件制造人批准书时批准的资料和程序，并且接受局方对质量系统的定期评审。（四）确保每一零部件符合经批准的设计，并且处于安全可用状态。（五）按照第十二章的要求为PMA件设置标牌或者标记。（六）用制造人的件号和名称、商标、符号或者局方接受的制造人其他标识方法，标识从制造人设施出厂的PMA件的任何部分。（七）对于每一PMA件，可获取用于确定制造符合性和适航性所需的设计资料。（八）保管取得零部件制造人批准书的相关文件，确保在局方要求时可获取。（九）局方可以获取其向供应商授权的所有相关信息。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A42:D42；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-10、UG-DAP-11、UG-DAP-15；版次 00（修订草案），名称见文件索引'),
(35, 'CCAR-21.319', '设计更改', '对零部件制造人批准书进行设计更改的规定如下：（一）设计更改的分类1.对PMA件设计的"小改"是指对批准基础没有显著影响的更改；2.对PMA件设计的"大改"是指除"小改"以外的其他更改。（二）设计更改的批准1.零部件制造人批准书持有人进行的PMA件设计小改。零部件制造人可以按照局方可接受的方式批准PMA件设计小改；2.零部件制造人批准书持有人进行的PMA件设计大改。在将设计大改纳入按PMA件的设计之前，零部件制造人批准书持有人应当获得局方的设计大改的批准。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A43:D43；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-06、UG-DAP-07、UG-DAP-08、UG-DAP-09；版次 00（修订草案），名称见文件索引'),
(36, 'CCAR-21.421', '民用航空产品的标牌或者标记', '（一）根据第五章或者第六章生产的民用航空产品上应当设置防火和不易损坏的清晰的标牌或者标记，其内容应当包括型号合格证编号或者生产许可证编号、制造人名称或者姓名、制造序列号、民用航空产品型号、制造日期。（二）航空器上的标牌应当固定在主舱门或者后舱门入口附近或者机尾附近的机身处明显位置；为进行合格审定而生产的原型航空器，在取得局方颁发的特许飞行证和临时登记证之前，应当在航空器上安装标牌，其内容应当包括制造人名称或者姓名、制造序列号、民用航空产品型号、制造日期。（三）航空发动机上的标牌应当固定在易于接近并在正常维护中不可能磨损或者丢失的位置。（四）螺旋桨的桨叶和桨毂上的标记应当固定在非关键表面上。（五）非常规航空器上的标牌或者标记应当固定在便于检查的适当位置。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A44:D44；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(37, 'CCAR-21.423', 'PMA件、CTSO件和关键件的标牌或者标记', '（一）应当为PMA件设置永久性的和清晰可辨的的标牌或者标记，标牌或者标记应当包括以下内容：1.制造人的名称、商标或者代号；2.PMA件的件号；3."CPMA"的字样。（二）应当为CTSO件设置永久性的和清晰可辨的的标牌或者标记，标牌或者标记应当包括以下内容：1.制造人的名称和地址；2.CTSO件的名称、型号、件号或者型别代号；3.CTSO件的序列号或者制造日期；4.对应的CTSO标准的编号。（三）在制造人的维修手册或者持续适航文件的适航限制部分中规定有更换时间、检查间隔或者相关工作程序的关键件，除了应当按照本条为其设置标牌或者标记之外，还应当将序列号永久性地和清晰可辨地标记在零部件上。（四）该零部件太小或者在该零部件上无法标记的，应当在该零部件随附的适航批准标签上标记不能在该零部件上标记的内容。', 'CCAR-21', '否', '是', NULL, '完整原文：法规原文!A45:D45；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAW-002 7；UG-DAP-04、UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(38, 'CCAR-21.425', '要求', '（一）除非局方认定为必要的情形外，不得在航空器、发动机、螺旋桨、螺旋桨叶片或者轮毂上拆除、更改、损坏或者放置第21.421条规定的标牌或者标记，或者在辅助动力装置上拆除、更改或者放置第21.423条要求的标牌或者标记。（二）局方认定为必要时，进行维修工作可以在维修过程中拆除或者安装第21.421条规定的标牌或者标记、或者第21.423条规定的辅助动力装置的标牌或者标记。（三）按照本条第（二）款拆除的航空器、发动机、螺旋桨、螺旋桨叶片或者轮毂上的标牌只能安装回原始位置。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A46:D46；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-04、UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(39, 'CCAR-21.431', '适用范围和定义', '（一）本章适用于修理方案和修理件生产的管理。（二）修理是指处理损伤并且将民用航空产品或者零部件恢复适航状态。（三）通过更换零部件而无需任何设计活动来处理损伤应当视为维修活动，不需要按照本规章进行批准。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A47:D47；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(40, 'CCAR-21.433', '修理方案', '（一）根据《一般运行和飞行规则》（CCAR91）第91.313条要求，对航空器及其部件实施修理时，应当符合以下规定：1.如果修理方案对飞机的重量、平衡、结构强度、性能、动力装置工作、飞行特性有显著影响或者影响适航性的其他特性，应当按照本规章的第二章、第三章或者第四章的适用要求，申请设计大改批准；2.除本款第1项的情况外，如果修理方案超出了航空器或者航空器部件制造厂家持续适航文件的规定，应当就修理方案的内容向局方申请批准后才能实施。（二）修理方案的申请人应当符合以下要求：1.表明对型号合格证、型号认可证、补充型号合格证、改装设计批准书或者补充型号认可证中规定的适航规章和环境保护要求、以及局方为建立与这些适航规章相同的安全水平所要求的专用条件的符合性；2.提交所有的验证资料；3.声明对本款第1项的适航规章和环境保护要求的符合性。（三）如果申请人不是型号合格证、型号认可证、补充型号合格证、改装设计批准书或者补充型号认可证持有人，则申请人可以通过使用其自己的资源或者通过与型号合格证、型号认可证、补充型号合格证、改装设计批准书或者补充型号认可证持有人之间的协议来符合本条第（一）款的要求。（四）局方在评审验证资料和进行必要的检查等审定工作后，确认其修理方案符合本条第（二）款的要求，可以批准该修理方案。（五）局方可以授权建立了局方可接受的设计保证系统的设计机构批准修理方案。（六）修理方案批准持有人应当向修理实施单位提供所有必需的指导及文件。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A48:D49；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(41, 'CCAR-21.437', '限制', '修理方案批准可能会带有限制。在带有限制的情况下，修理方案批准应当包含所有必要的要求和限制。这些要求和限制应当由修理方案批准持有人按照局方可接受的方式提供给运营人。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A50:D50；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(42, 'CCAR-21.439', '记录保存', '对每项修理，所有相关的信息、图纸、试验报告、根据第21.437条颁发的要求和限制以及批准证据都应当由修理方案批准持有人保存，直至实施了该项修理的民用航空产品永久退役，以便提供必要信息来确保修理过的民用航空产品和零部件的持续适航。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A51:D51；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(43, 'CCAR-21.441', '持续适航文件', '（一）修理方案批准持有人应当为修理过的航空器的每一运营人至少提供一套由于修理方案产生的持续适航文件的修改部分，包含描述资料和需要完成的指令。修理过的民用航空产品或者零部件可以在提供持续适航文件的修改部分之前交付使用，但是应当限制使用时间并经局方批准。任何需要符合持续适航文件的修改部分中的要求的人都应当可以获得持续适航文件的修改部分。（二）首次批准修理之后修理方案批准持有人对持续适航文件的修改部分进行更新时，这些更新应当提供给每一运营人，并且任何需要符合持续适航文件的修改部分中的要求的人都应当可以获得这些更新。表明如何发放更新的持续适航文件的修改部分的程序应当提交局方。', 'CCAR-21', '是', '否', NULL, '完整原文：法规原文!A52:D52；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(44, '附录D一（一）', '对第一类设计机构许可证申请及持有人审查要求', '（一）任命一名责任经理，以确保机构内的所有设计活动均按照要求的标准进行，并且设计机构持续符合设计保证系统要求以及设计保证手册中规定的程序；', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A53:D53；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 1、3；UG-DAP-03；版次 00（修订草案），名称见文件索引'),
(45, '附录D一（二）', '对第一类设计机构许可证申请及持有人审查要求', '（二）责任经理应任命以下人员并明确其职责：1.适航经理，负责设计保证系统适航职能履行；2.独立监督负责人，负责设计保证系统独立监督职能履行；3.安全经理（如适用），负责组织开展设计保证系统安全管理工作；4.根据机构规模及其活动的性质和复杂程度，为确保设计机构符合本规定要求所需的其他任何人员。设计机构可根据自身实际情况，在确保职责完整的前提下，合并设置责任经理及上述各管理人员，但须保持独立监督职能对设计及适航职能的独立性。', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A54:D54；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 3；UG-DAP-03；版次 00（修订草案），名称见文件索引'),
(46, '附录D一（三）', '对第一类设计机构许可证申请及持有人审查要求', '（三）符合以下任一条件时，设计机构可以不设适航经理，本章设计保证系统适航职能将由责任经理直接负责：1.设计机构许可项目单所规定的设计机构活动或者工作范围仅限于设计小改和/或未构成设计大改的修理设计；2.设计机构没有指定的适航经理，且在责任经理的直接监督下履行该功能与机构活动的范围和程度是相称的。', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A55:D55；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(47, '附录D一（四）', '对第一类设计机构许可证申请及持有人审查要求', '（四）设计机构按第（三）条任命的人员应：1.对责任经理负责，并能直接向其汇报；2.具备履行其职责所需的适当知识、背景和经验。', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A56:D56；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-03 6 及附表一；版次 00（修订草案），名称见文件索引'),
(48, '附录D一（五）', '对第一类设计机构许可证申请及持有人审查要求', '（五）设计机构应确保：1.所有技术部门应当配备足够数量和经验的员工，并且被赋予适当的权限以履行他们的职责。同时，技术部门的办公环境、设施和设备应当能够满足其员工的工作需求，以确保民用航空产品符合适航规章和环境保护要求；2.各部门之间和部门内部在适航和环境保护事项方面有充分、高效的沟通和协调。', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A57:D57；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 3；UG-DAP-03、UG-DAP-04；版次 00（修订草案），名称见文件索引'),
(49, '附录D一（六）', '对第一类设计机构许可证申请及持有人审查要求', '（六）第一类设计机构许可证的申请人和持有人应建立、实施并保持一类设计保证系统，该系统包括安全管理要素和设计保证要素，并在整个机构内有明确的问责制和清晰界定的职责分工；', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A58:D58；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 0.2、3～6；UG-DAP-01～15；版次 00（修订草案），名称见文件索引'),
(50, '附录D一（七）', '对第一类设计机构许可证申请及持有人审查要求', '（七）设计机构应在责任经理的直接领导下建立、实施和保持设计保证系统。设计保证系统应与机构规模、活动性质和复杂程度相匹配，同时考虑活动固有的危险源和相应的风险；', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A59:D59；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 3、6；UG-DAP-03、UG-DAP-13；版次 00（修订草案），名称见文件索引'),
(51, '附录D一（八）', '对第一类设计机构许可证申请及持有人审查要求', '（八）申请取得及持有最大起飞重量1360公斤以上航空器，以及涡轮航空发动机、变距螺旋桨型号合格证的设计机构，其设计保证系统应涵盖完整的安全管理要素。设计机构设计保证系统的安全管理要素包括：1.建立、实施和保持安全政策和相应的安全目标；2.任命关键安全人员；3.建立、实施并保持安全风险管理过程，以识别其活动所涉及的航空安全危险源，评估危险源并管理相关风险，包括采取措施缓解风险并验证其有效性；4.建立、实施并保持安全保证过程，包括：(1)设计机构安全表现的评估和监测；(2)对设计保证系统的变更进行管理；(3)安全管理要素持续改进的原则。5.在设计机构内通过培训、教育和交流，以促进安全。6.建立故障、失效、缺陷事件报告系统，以促进对安全的持续改进。', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A60:D60；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(52, '附录D一（九）', '对第一类设计机构许可证申请及持有人审查要求', '（九）设计保证要素包括：1.建立、实施并保持系统，用于控制和监督其设计机构许可项目单范围内的民用航空产品和零部件的设计、设计更改和修理设计等活动；该系统应：(1)包括适航职能，负责确保民用航空产品和零部件的设计、设计更改和修理设计，符合适用的适航规章和环境保护要求，以及民航局规定的专用条件；(2)确保其按照本规定和根据设计机构许可项目单，正确履行其职责；2.建立、实施并保持独立的核查功能，用以表明符合适用的适航规章和环境保护要求，以及民航局规定的专用条件；3.详细说明设计保证系统如何根据其书面程序所规定的方式，确保对其供应商设计零部件或执行任务的可接受性进行管控。', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A61:D61；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-04、UG-DAP-07、UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(53, '附录D一（十）', '对第一类设计机构许可证申请及持有人审查要求', '（十）设计机构应在设计保证系统中建立独立的监督功能，以确认机构是否符合本规定的相关要求，以及设计保证系统的符合性和充分性。本功能还应包括向独立监督负责人和责任经理提供反馈，以确保在必要时采取纠正措施。', 'AP-21-18 附录D', '部分', '否', NULL, '完整原文：法规原文!A62:D62；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-13、UG-DAP-14；UG-DAF-05A～05C；版次 00（修订草案），名称见文件索引'),
(54, '附录D二', '对第二类设计机构许可证申请及持有人审查要求', '本条完整要求分 3 段列于“法规原文”第 63～65 行，须连续逐款核对。
要求主题：附录D二 对第二类设计机构许可证申请及持有人审查要求
不得仅依据本行的自评说明代替条款全文。', 'AP-21-18 附录D', '部分', '是', NULL, '完整原文：法规原文!A63:D65；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 设计保证手册 00（修订草案）第 2 章；UG-DAP-02 设计保证系统更改管理程序 00'),
(55, '附录D三（一）', '第一类及第二类设计机构许可证申请及持有人的设计保证手册要求', '（一）作为设计保证系统的一部分，设计机构应当制定并提交符合局方要求的设计保证手册。设计保证手册应当直接描述或者通过引用其他文件的方式描述其组织架构、相关政策、流程和程序、设计活动类型，以及设计机构拟申请的设计机构许可项目单所涵盖的民用航空产品和零部件类别；若涉及与设计供应商的合作，还应说明相关接口和对设计供应商的管控情况。如果要开展试飞，设计机构还应编制并提交试飞管理手册，该手册应明确与试飞相关的政策和程序，具体内容应包括：1.对机构试飞流程的描述，包括与特许飞行证颁发相关的支持性工作；2.机组人员政策，包括机组人员组成、能力要求、执照有效期和飞行时间限制等；3.搭载非机组人员及开展试飞训练的相关程序；4.风险和安全管理政策及相应方法；5.识别并确定需搭载的仪器和设备的程序；6.试飞所需的文件清单。', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A66:D66；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 全文；UG-DAP-10；版次 00（修订草案），名称见文件索引'),
(56, '附录D三（二）', '第一类及第二类设计机构许可证申请及持有人的设计保证手册要求', '（二）如果产品的任何零部件或者更改是由供应商负责设计的，设计保证手册应当声明设计机构如何保证所有零部件经过全面符合性核查的要求，并且应当在手册中直接给出或者通过引用其他文件的方式提供有关这些供应商的设计活动和机构情况的必要描述和信息，以支撑上述声明。', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A67:D67；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-10、UG-DAP-07；版次 00（修订草案），名称见文件索引'),
(57, '附录D三（三）', '第一类及第二类设计机构许可证申请及持有人的设计保证手册要求', '（三）设计保证手册应当及时修订，以确保其对机构情况的描述能够反映设计机构的最新状态，并且修订后的手册应当提交给局方。', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A68:D68；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-01、UG-DAP-02；版次 00（修订草案），名称见文件索引'),
(58, '附录D三（四）', '第一类及第二类设计机构许可证申请及持有人的设计保证手册要求', '（四）设计机构应当制定并保持一份声明，说明包括责任经理和适航经理在内的管理人员，以及机构内其他负责适航和环境保护相关事项做出决策的人员的资历和经验说明，并将该声明提交给局方。', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A69:D69；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01-附1；UG-DAP-03；版次 00（修订草案），名称见文件索引'),
(59, '附录D四（一）', '第一类及第二类设计机构许可证申请及持有人的责任要求', '（一）维护设计保证手册，使其与设计保证系统一致；', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A70:D70；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-01、UG-DAP-02；版次 00（修订草案），名称见文件索引'),
(60, '附录D四（二）', '第一类及第二类设计机构许可证申请及持有人的责任要求', '（二）确保设计保证手册及其引用的相关程序，在设计机构内部设计保证手册作为基本的工作文件使用；', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A71:D71；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-01、UG-DAP-03；UG-DAW-006；版次 00（修订草案），名称见文件索引'),
(61, '附录D四（三）', '第一类及第二类设计机构许可证申请及持有人的责任要求', '（三）接受局方对设计保证系统的定期评审；', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A72:D72；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-15、UG-DAP-13、UG-DAP-14；版次 00（修订草案），名称见文件索引'),
(62, '附录D四（四）', '第一类及第二类设计机构许可证申请及持有人的责任要求', '（四）确认民用航空产品的设计、设计更改或者修理设计符合适用的适航规章和环境保护要求，并且没有不安全的特征；', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A73:D73；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-07；UG-DAF-03、UG-DAF-17；版次 00（修订草案），名称见文件索引'),
(63, '附录D四（五）', '第一类及第二类设计机构许可证申请及持有人的责任要求', '（五）除按照获得的DOA权利批准设计小改或者未构成设计大改的修理设计之外，向局方提交证明符合本条第（四）款的符合性声明及相关文件；', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A74:D74；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-07、UG-DAP-08、UG-DAP-09；版次 00（修订草案），名称见文件索引'),
(64, '附录D四（六）', '第一类及第二类设计机构许可证申请及持有人的责任要求', '（六）设计批准持有人应当向局方提供局方要求的设计更改相关信息；', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A75:D75；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-11 6 步骤 5；UG-DAP-15；版次 00（修订草案），名称见文件索引'),
(65, '附录D四（七）', '第一类及第二类设计机构许可证申请及持有人的责任要求', '（七）经局方批准的设计机构在其设计机构许可项目单范围内发布的数据和信息，须附如下声明：“本资料由经CAAC批准的__________号设计机构许可证持有人按照设计机构许可项目单明确的权利范围进行批准。”;', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A76:D76；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAP-11 6 步骤 4；UG-DAP-08；版次 00（修订草案），名称见文件索引'),
(66, '附录D四（八）', '第一类及第二类设计机构许可证申请及持有人的责任要求', '（八）持续符合本规定的适用要求。', 'AP-21-18 附录D', '是', '是', NULL, '完整原文：法规原文!A77:D77；本表为发布前自评底稿，实际符合性未确认。', 'UG-DAM-01 6；UG-DAP-02、UG-DAP-13～15；版次 00（修订草案），名称见文件索引')
ON CONFLICT (seq) DO NOTHING;
